package cn.zhuatech.retail.service;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;class PromotionReleaseGovernanceServiceTest{private final PromotionReleaseGovernanceService service=new PromotionReleaseGovernanceService();@Test void activatesControlledPromotion(){var r=service.assess(new PromotionReleaseGovernanceService.Request("M1",true,3000,2000,true,true,true,true,true,true));assertThat(r.decision()).isEqualTo(PromotionReleaseGovernanceService.Decision.ACTIVATE);}@Test void blocksCommercialConfigurationFailures(){var r=service.assess(new PromotionReleaseGovernanceService.Request("M2",false,1000,2000,false,false,false,true,true,true));assertThat(r.blockers()).hasSize(5);}@Test void reviewsOperationalReadiness(){var r=service.assess(new PromotionReleaseGovernanceService.Request("M3",true,3000,2000,true,true,true,false,false,false));assertThat(r.actions()).hasSize(3);}}
